using System.Windows;
namespace ChichiCapture;public partial class SettingsWindow:Window{readonly AppSettings s;public SettingsWindow(AppSettings settings){InitializeComponent();s=settings;Ctrl.IsChecked=s.Ctrl;Shift.IsChecked=s.Shift;Alt.IsChecked=s.Alt;WindowCtrl.IsChecked=s.WindowCtrl;WindowShift.IsChecked=s.WindowShift;WindowAlt.IsChecked=s.WindowAlt;foreach(char c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"){KeyBox.Items.Add(c.ToString());WindowKeyBox.Items.Add(c.ToString());}KeyBox.SelectedItem=((char)s.HotKey).ToString();WindowKeyBox.SelectedItem=((char)s.WindowHotKey).ToString();}void Save_Click(object sender,RoutedEventArgs e){if(Ctrl.IsChecked!=true&&Shift.IsChecked!=true&&Alt.IsChecked!=true||WindowCtrl.IsChecked!=true&&WindowShift.IsChecked!=true&&WindowAlt.IsChecked!=true){MessageBox.Show("각 단축키에 Ctrl, Shift, Alt 중 하나 이상을 선택하세요.");return;}s.Ctrl=Ctrl.IsChecked==true;s.Shift=Shift.IsChecked==true;s.Alt=Alt.IsChecked==true;s.HotKey=(int)((string)KeyBox.SelectedItem)[0];s.WindowCtrl=WindowCtrl.IsChecked==true;s.WindowShift=WindowShift.IsChecked==true;s.WindowAlt=WindowAlt.IsChecked==true;s.WindowHotKey=(int)((string)WindowKeyBox.SelectedItem)[0];DialogResult=true;}}
